export const normalizeCategoryTree = (rawCategories) => {
  const tree = {};

  Object.entries(rawCategories || {}).forEach(([mainCategory, rawSubNode]) => {
    if (Array.isArray(rawSubNode)) {
      tree[mainCategory] = Object.fromEntries(
        rawSubNode.filter(Boolean).map((subCategory) => [subCategory, []])
      );
      return;
    }

    if (rawSubNode && typeof rawSubNode === 'object') {
      const normalizedSubMap = {};

      Object.entries(rawSubNode).forEach(([subCategory, rawSuperSubNode]) => {
        if (Array.isArray(rawSuperSubNode)) {
          normalizedSubMap[subCategory] = Array.from(new Set(rawSuperSubNode.filter(Boolean)));
          return;
        }

        if (typeof rawSuperSubNode === 'string' && rawSuperSubNode.trim()) {
          normalizedSubMap[subCategory] = [rawSuperSubNode.trim()];
          return;
        }

        normalizedSubMap[subCategory] = [];
      });

      tree[mainCategory] = normalizedSubMap;
      return;
    }

    tree[mainCategory] = {};
  });

  return tree;
};

export const getSubCategoryMap = (categoryTree, mainCategory) => {
  const normalizedTree = normalizeCategoryTree(categoryTree);
  return normalizedTree[mainCategory] || {};
};

export const getSuperSubOptions = (categoryTree, mainCategory, subCategory) => {
  const subMap = getSubCategoryMap(categoryTree, mainCategory);
  return Array.isArray(subMap[subCategory]) ? subMap[subCategory] : [];
};
